-- Isolated feature-request contracts. No hosted target/provider operation.
begin;
do $$begin if current_database()<>'commerce_test' or inet_server_addr() not in ('127.0.0.1'::inet,'::1'::inet) then raise exception 'Isolated loopback commerce_test required';end if;end$$;
insert into auth.users(id,email,email_confirmed_at) values
 ('e7100000-0000-4000-8000-000000000001','request-owner-a@example.test',now()),
 ('e7100000-0000-4000-8000-000000000002','request-owner-b@example.test',now()),
 ('e7100000-0000-4000-8000-000000000003','request-customer@example.test',now()),
 ('e7100000-0000-4000-8000-000000000004','request-unverified@example.test',null),
 ('e7100000-0000-4000-8000-000000000005','request-next-owner@example.test',now());
insert into public.commerce_websites(id,slug,name,status,owner_permissions) values
 ('e7200000-0000-4000-8000-000000000001','feature-request-a','Feature request A','active','{}'),
 ('e7200000-0000-4000-8000-000000000002','feature-request-b','Feature request B','setup','{}');
insert into public.commerce_memberships(website_id,user_id) values
 ('e7200000-0000-4000-8000-000000000001','e7100000-0000-4000-8000-000000000001'),
 ('e7200000-0000-4000-8000-000000000002','e7100000-0000-4000-8000-000000000002');
select commerce_test.check_true(has_function_privilege('authenticated','public.commerce_feature_requests_owner(uuid,text,jsonb)','EXECUTE') and not has_function_privilege('anon','public.commerce_feature_requests_owner(uuid,text,jsonb)','EXECUTE') and not has_function_privilege('service_role','public.commerce_feature_requests_owner(uuid,text,jsonb)','EXECUTE'),'feature request owner RPC grants authenticated only');
select commerce_test.check_true(has_function_privilege('service_role','public.commerce_feature_requests_admin(uuid,text,jsonb,text)','EXECUTE') and not has_function_privilege('anon','public.commerce_feature_requests_admin(uuid,text,jsonb,text)','EXECUTE') and not has_function_privilege('authenticated','public.commerce_feature_requests_admin(uuid,text,jsonb,text)','EXECUTE'),'feature request Admin RPC grants service only');
select commerce_test.check_true(not has_table_privilege('authenticated','public.commerce_feature_requests','INSERT,UPDATE,DELETE,TRUNCATE') and not has_table_privilege('service_role','public.commerce_feature_requests','SELECT,INSERT,UPDATE,DELETE,TRUNCATE') and not has_table_privilege('anon','public.commerce_feature_requests','SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'feature request tables expose only authenticated SELECT, never direct mutation');
select commerce_test.check_true(not has_table_privilege('authenticated','commerce_private.feature_request_events','SELECT,INSERT,UPDATE,DELETE,TRUNCATE') and not has_table_privilege('service_role','commerce_private.feature_request_events','SELECT,INSERT,UPDATE,DELETE,TRUNCATE') and not exists(select 1 from pg_policies where schemaname='commerce_private' and tablename='feature_request_events'),'private feature history has no direct API role access or policies');
select commerce_test.check_true((select relrowsecurity from pg_class where oid='public.commerce_feature_requests'::regclass) and (select relrowsecurity from pg_class where oid='commerce_private.feature_request_events'::regclass),'both new feature request relations enable RLS');
select commerce_test.check_true(not has_function_privilege('authenticated','commerce_private.feature_request_detail(uuid,uuid)','EXECUTE') and not has_function_privilege('service_role','commerce_private.feature_request_page(uuid,jsonb)','EXECUTE') and not has_function_privilege('authenticated','commerce_private.record_feature_request_event()','EXECUTE'),'private feature request projections and history triggers revoke direct execution');
set local role anon;
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001')$q$,'anonymous user cannot list feature requests',array['42501']);
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001')$q$,'missing owner identity cannot list feature requests',array['42501']);
select set_config('request.jwt.claim.sub','e7100000-0000-4000-8000-000000000004',true);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001')$q$,'unverified owner identity cannot list feature requests',array['42501']);
select set_config('request.jwt.claim.sub','e7100000-0000-4000-8000-000000000003',true);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001')$q$,'customer identity cannot list owner feature requests',array['42501']);
select set_config('request.jwt.claim.sub','e7100000-0000-4000-8000-000000000001',true);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000002')$q$,'owner cannot read another website feature requests',array['42501']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner(null)$q$,'owner cannot request a global feature queue',array['42501']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','review','{}')$q$,'owner cannot choose an administrative review action',array['22023']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','list','{"extra":true}')$q$,'owner list rejects unknown payload fields',array['22023']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','list','{"before_id":"e7300000-0000-4000-8000-000000000001"}')$q$,'list rejects a half cursor',array['22023']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','list','{"before_id":"e7300000-0000-4000-8000-000000000001","before_created_at":"yesterday"}')$q$,'list rejects a non-ISO cursor',array['22023']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit','{"submission_key":"e7300000-0000-4000-8000-000000000001","title":"Bad","description":"Valid long description"}')$q$,'submission rejects an undersized title',array['22023']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit','{"submission_key":"e7300000-0000-4000-8000-000000000001","title":"Valid title","description":false}')$q$,'submission rejects non-text description',array['22023']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit','{"submission_key":"e7300000-0000-4000-8000-000000000001","title":"Valid title","description":"A proper description","status":"approved"}')$q$,'owner cannot submit privileged status fields',array['22023']);
select commerce_test.record('feature_original',public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit','{"submission_key":"e7300000-0000-4000-8000-000000000001","title":"  Size chart request  ","description":"  Please add a configurable size chart for this store.  "}'));
select commerce_test.check_true((select value->'request'->>'title'='Size chart request' and value->'request'->>'status'='submitted' and value->'request'->>'revision'='1' and value->'replayed'='false'::jsonb and jsonb_array_length(value->'events')=1 and value->'events'->0->>'actor_kind'='owner' and value->'events'->0->'from_status'='null'::jsonb from commerce_test.state where key='feature_original'),'owner request initializes trimmed immutable content, original state and one event without product/order permissions');
select commerce_test.check_true((select (value->'request')-array['id','website_id','title','description','status','revision','review_note','assignment_reference','created_at','updated_at']='{}'::jsonb and (value->'events'->0)-array['id','request_id','revision','from_status','to_status','note','assignment_reference','actor_kind','created_at']='{}'::jsonb and value::text not like '%actor_email%' and value::text not like '%submission_key%' and value::text not like '%submitted_by%' from commerce_test.state where key='feature_original'),'owner request DTO excludes internal keys, submitter identity and Admin actor email');
select commerce_test.check_true(public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit','{"submission_key":"e7300000-0000-4000-8000-000000000001","title":"Size chart request","description":"Please add a configurable size chart for this store."}')->'replayed'='true'::jsonb,'identical owner submission retry returns original request');
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit','{"submission_key":"e7300000-0000-4000-8000-000000000001","title":"Changed feature request","description":"Please add a configurable size chart for this store."}')$q$,'changed owner submission replay conflicts without rewrite',array['23505']);
select commerce_test.check_true((select count(*)=1 from public.commerce_feature_requests),'owner direct RLS reads only their own website');
select commerce_test.must_fail($q$select submitted_by,submission_key,last_action_key from public.commerce_feature_requests$q$,'owner column grants hide internal submitter and replay keys',array['42501']);
select commerce_test.must_fail($q$update public.commerce_feature_requests set review_note='Owner cannot decide requests'$q$,'authenticated owner cannot directly mutate request rows',array['42501']);
select commerce_test.must_fail($q$select * from commerce_private.feature_request_events$q$,'owner cannot bypass safe private history projection',array['42501']);
select set_config('request.jwt.claim.sub','e7100000-0000-4000-8000-000000000002',true);
select commerce_test.check_true((select count(*)=0 from public.commerce_feature_requests),'another active owner sees no foreign request rows');
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000002','get',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original')))$q$,'foreign website cannot resolve known feature request UUID',array['42501']);
select commerce_test.record('feature_other',public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000002','submit','{"submission_key":"e7300000-0000-4000-8000-000000000002","title":"Grocery delivery request","description":"Please review scheduled grocery delivery as a separate task."}'));
select commerce_test.check_true(jsonb_array_length(public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000002')->'requests')=1,'setup website owner can submit and list only its requirement');
select set_config('request.jwt.claim.role','service_role',true);
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin(null,'list','{}','admin@example.test')$q$,'forged service JWT claim does not grant Admin request review',array['42501']);
reset role;

-- Existing business/configuration rows must not change during an Admin decision.
create temporary table feature_business_before(table_name text primary key,rows jsonb) on commit drop;
do $$declare r record;v jsonb;begin
 for r in select n.nspname schema_name,c.relname table_name from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','commerce_private','auth','storage','cron') and c.relkind='r' and not ((n.nspname='public' and c.relname in ('commerce_feature_requests','commerce_audit_logs')) or (n.nspname='commerce_private' and c.relname='feature_request_events')) loop
  execute format('select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),''[]''::jsonb) from %I.%I x',r.schema_name,r.table_name) into v;insert into feature_business_before values(r.schema_name||'.'||r.table_name,v);
 end loop;end$$;
set local role service_role;
select set_config('request.jwt.claim.sub','',true);
select commerce_test.check_true(jsonb_array_length(public.commerce_feature_requests_admin(null,'list','{}','admin@example.test')->'requests')=2 and public.commerce_feature_requests_admin(null,'list','{}','admin@example.test')->'website_id'='null'::jsonb,'signed-service global queue lists both tenant requests with null top-level website');
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin(null,'get','{}','admin@example.test')$q$,'Admin detail requires a bound website',array['22023']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','get',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_other')),'admin@example.test')$q$,'Admin cannot get a request using another bound website',array['42501']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin(null,'list','{}','not-an-email')$q$,'Admin action rejects missing or malformed actor identity',array['22023']);
select commerce_test.record('feature_review',public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','submitted','expected_revision',1,'status','under_review','note','Reviewing the size chart requirement.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000001'),'admin@example.test'));
select commerce_test.check_true((select value->'request'->>'status'='under_review' and value->'request'->>'revision'='2' and jsonb_array_length(value->'events')=2 and value->'action_event'->>'actor_kind'='admin' and value->'replayed'='false'::jsonb and value::text not like '%admin@example.test%' from commerce_test.state where key='feature_review'),'Admin review atomically appends projected history without exposing actor email');
select commerce_test.check_true(public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','submitted','expected_revision',1,'status','under_review','note','Reviewing the size chart requirement.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000001'),'admin@example.test')->'replayed'='true'::jsonb,'identical Admin action retry returns the original durable event');
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','submitted','expected_revision',1,'status','under_review','note','Different review note.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000001'),'admin@example.test')$q$,'changed action-key replay cannot rewrite the saved decision',array['23505']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','submitted','expected_revision',1,'status','approved','note','Stale competing approval.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000099'),'admin@example.test')$q$,'stale review status and revision reject without lost decisions',array['23505']);
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','under_review','expected_revision',2,'status','assigned','note','Skipping approval is not allowed.','assignment_reference','TASK-unsafe','action_key','e7400000-0000-4000-8000-000000000098'),'admin@example.test')$q$,'review cannot skip approval to assign development work',array['23505']);
select commerce_test.record('feature_approved',public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','under_review','expected_revision',2,'status','approved','note','Approved for a separate controlled task.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000002'),'admin@example.test'));
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','approved','expected_revision',3,'status','assigned','note','Needs an actual work reference.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000097'),'admin@example.test')$q$,'assigned review requires a nonempty bounded assignment reference',array['22023']);
select commerce_test.record('feature_assigned',public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','approved','expected_revision',3,'status','assigned','note','Queued for development; no release or activation.','assignment_reference','TASK-LOCAL-1','action_key','e7400000-0000-4000-8000-000000000003'),'admin@example.test'));
select commerce_test.check_true((select value->'request'->>'status'='assigned' and value->'request'->>'revision'='4' and value->'request'->>'assignment_reference'='TASK-LOCAL-1' and jsonb_array_length(value->'events')=4 from commerce_test.state where key='feature_assigned'),'request can be reviewed approved and assigned with four immutable ordered events');
select commerce_test.check_true((public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','submitted','expected_revision',1,'status','under_review','note','Reviewing the size chart requirement.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000001'),'admin@example.test')->'request'->>'status')='assigned','replaying an earlier action returns current history without rewinding later decisions');
select commerce_test.must_fail($q$select public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000001','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original'),'expected_status','assigned','expected_revision',4,'status','rejected','note','Cannot reopen assigned work.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000096'),'admin@example.test')$q$,'assigned work cannot be reopened or redecided',array['23505']);
select commerce_test.record('feature_rejected',public.commerce_feature_requests_admin('e7200000-0000-4000-8000-000000000002','review',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_other'),'expected_status','submitted','expected_revision',1,'status','rejected','note','Declined for this website.','assignment_reference','','action_key','e7400000-0000-4000-8000-000000000004'),'admin@example.test'));
select commerce_test.check_true((select value->'request'->>'status'='rejected' and jsonb_array_length(value->'events')=2 from commerce_test.state where key='feature_rejected'),'Admin may reject a submitted request without changing website configuration');
reset role;
do $$declare r record;v jsonb;begin
 for r in select * from feature_business_before loop
  execute format('select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),''[]''::jsonb) from %I.%I x',split_part(r.table_name,'.',1),split_part(r.table_name,'.',2)) into v;
  if v is distinct from r.rows then raise exception 'Feature decisions changed unrelated records: %',r.table_name;end if;
 end loop;end$$;
select commerce_test.check_true(true,'feature submission/review/assignment changes no existing feature flags, permissions, orders, payments, wallets or cron rows');
select commerce_test.check_true((select count(*)=3 from public.commerce_audit_logs where action='review_feature_request' and website_id='e7200000-0000-4000-8000-000000000001') and (select count(*)=4 from commerce_private.feature_request_events where request_id=(select(value->'request'->>'id')::uuid from commerce_test.state where key='feature_original')),'identical review retries add neither duplicate history nor duplicate Admin audit');
select commerce_test.must_fail($q$update public.commerce_feature_requests set title='A rewritten original request' where website_id='e7200000-0000-4000-8000-000000000001'$q$,'even privileged direct updates cannot rewrite original request content',array['42501']);
select commerce_test.must_fail($q$delete from public.commerce_feature_requests where website_id='e7200000-0000-4000-8000-000000000001'$q$,'even privileged direct deletion cannot remove retained request history',array['42501']);
select commerce_test.must_fail($q$update commerce_private.feature_request_events set note='A rewritten history event' where website_id='e7200000-0000-4000-8000-000000000001'$q$,'immutable feature event notes cannot be rewritten',array['42501']);
select commerce_test.must_fail($q$delete from commerce_private.feature_request_events where website_id='e7200000-0000-4000-8000-000000000001'$q$,'immutable feature events cannot be deleted',array['42501']);
update public.commerce_websites set status='suspended' where id='e7200000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','e7100000-0000-4000-8000-000000000001',true);
select commerce_test.check_true(public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','get',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original')))->'request'->>'status'='assigned','retained active owner can read request status while website is suspended');
select commerce_test.check_true(public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit','{"submission_key":"e7300000-0000-4000-8000-000000000001","title":"Size chart request","description":"Please add a configurable size chart for this store."}')->'replayed'='true'::jsonb,'read-only website permits immutable known submission replay for recovery');
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit','{"submission_key":"e7300000-0000-4000-8000-000000000099","title":"New suspended request","description":"This should not create a new request."}')$q$,'suspended website cannot create new feature requirements',array['42501']);
reset role;
update public.commerce_websites set status='active' where id='e7200000-0000-4000-8000-000000000001';
update auth.users set email_confirmed_at=null where id='e7100000-0000-4000-8000-000000000001';
set local role authenticated;
select commerce_test.check_true((select count(*)=0 from public.commerce_feature_requests),'withdrawn live verification removes direct RLS visibility');
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001')$q$,'withdrawn verification blocks owner RPC reads',array['42501']);
reset role;
update auth.users set email_confirmed_at=now() where id='e7100000-0000-4000-8000-000000000001';
update public.commerce_memberships set active=false where website_id='e7200000-0000-4000-8000-000000000001' and user_id='e7100000-0000-4000-8000-000000000001';
insert into public.commerce_memberships(website_id,user_id) values('e7200000-0000-4000-8000-000000000001','e7100000-0000-4000-8000-000000000005');
set local role authenticated;
select commerce_test.check_true((select count(*)=0 from public.commerce_feature_requests),'revoked owner loses direct request RLS access');
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001')$q$,'revoked owner loses feature-request RPC access',array['42501']);
select set_config('request.jwt.claim.sub','e7100000-0000-4000-8000-000000000005',true);
select commerce_test.check_true((select count(*)=1 from public.commerce_feature_requests) and public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','get',jsonb_build_object('request_id',(select value->'request'->>'id' from commerce_test.state where key='feature_original')))->'request'->>'status'='assigned','explicitly assigned current owner can read retained website business requests');
reset role;
update public.commerce_memberships set active=false where website_id='e7200000-0000-4000-8000-000000000001' and user_id='e7100000-0000-4000-8000-000000000005';
update public.commerce_memberships set active=true where website_id='e7200000-0000-4000-8000-000000000001' and user_id='e7100000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','e7100000-0000-4000-8000-000000000001',true);
select commerce_test.must_fail($q$select public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit',jsonb_build_object('submission_key','e7300000-0000-4000-8000-000000000090','title',repeat('🙂',3),'description','A valid description for Unicode minimum checks.'))$q$,'request title minimum counts Unicode characters rather than UTF-16 code units',array['22023']);
select commerce_test.check_true(char_length(public.commerce_feature_requests_owner('e7200000-0000-4000-8000-000000000001','submit',jsonb_build_object('submission_key','e7300000-0000-4000-8000-000000000091','title',repeat('🙂',5),'description',repeat('அ',6000)))->'request'->>'description')=6000,'bounded request payload accepts 6000 genuine Indian-language characters without the unrelated customer 16KiB cap');
reset role;
select commerce_test.check_true(not exists(select 1 from public.commerce_feature_requests r where r.revision<>(select count(*) from commerce_private.feature_request_events e where e.website_id=r.website_id and e.request_id=r.id)),'all retained feature request revisions match immutable event counts');
commit;
